def comps(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]; seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col==bg or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c));pts=[]
   while q:
    y,x=q.pop();pts.append((y,x))
    for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col: seen.add((ny,nx));q.append((ny,nx))
   r0=min(y for y,x in pts);r1=max(y for y,x in pts);c0=min(x for y,x in pts);c1=max(x for y,x in pts);box=(r1-r0+1)*(c1-c0+1)
   out.append((col,(r0,r1,c0,c1),len(pts),box,round(len(pts)/box,2)))
 return bg,out
